#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LEN 1024
#define ARRAY_SIZE 256

int main(int argc, char *argv[])
{
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    if (strlen(s1) >= MAX_LEN + 1 || strlen(s2) >= MAX_LEN + 1) {
        puts("TOO_LONG");
        return 0;
    }
    int freq1[ARRAY_SIZE] = {0};
    int freq2[ARRAY_SIZE] = {0};
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;
        if (c >= 'A' && c <= 'Z') c = (unsigned char)(c + ('a' - 'A'));
        ++freq1[c];
    }
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;
        if (c >= 'A' && c <= 'Z') c = (unsigned char)(c + ('a' - 'A'));
        ++freq2[c];
    }
    int is_anagram = 1;
    for (int i = 0; i < ARRAY_SIZE; ++i) {
        if (freq1[i] != freq2[i]) { is_anagram = 0; break; }
    }
    puts(is_anagram ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
